/* Pato UC15: questões das aulas 1–5 + prova T10 (28/11/2025) */
window.UC={q:[{"a": 2, "t": "Febre reumática — cardite (T10 Q1)", "e": "Sobre a febre reumática e suas manifestações cardíacas, assinale a alternativa correta:", "o": ["A cardite reumática subclínica só pode ser diagnosticada por elevação de marcadores inflamatórios (VHS/PCR).", "A cardite reumática acomete exclusivamente o endocárdio, poupando miocárdio e pericárdio.", "A miocardite reumática pode cursar com bloqueios AV e arritmias devido ao dano inflamatório difuso no miocárdio e apresenta as lesões típicas denominadas corpúsculos de Aschoff.", "Na fase aguda, a valvulite reumática caracteriza-se por vegetações grandes, friáveis, ricas em microrganismos.", "A pericardite reumática, na forma exsudativa, é a complicação mais frequente."], "c": 2, "x": "Gabarito C. Subclínica = eco com Doppler (não “só” VHS/PCR); é PANcardite; as vegetações reumáticas são pequenas e ESTÉREIS (grandes/friáveis/com germes = endocardite infecciosa); a principal manifestação é a valvulite.", "r": "SP2 · Pancardite reumática", "p": 1},{"a": 1, "t": "Síndrome nefrótica (T10 Q2)", "e": "Analise as seguintes afirmativas sobre a síndrome nefrótica:", "o": ["I, II e III", "II, IV e V", "I, III e V", "II, III e V", "III, IV e V"], "c": 3, "x": "Gabarito D (II, III e V). I e IV descrevem a NEFRÍTICA (inflamação capilar, proteinúria não maciça, hematúria com cilindros hemáticos). Na nefrótica a proteinúria é MACIÇA.", "r": "SP1 · Síndrome nefrótica", "it": ["Na síndrome nefrótica há inflamação dos capilares glomerulares, com proteinúria leve e redução da TFG.", "A lipidúria ocorre pela filtração glomerular aumentada de lipoproteínas e formação de cilindros gordurosos.", "A perda urinária de antitrombina III contribui para risco aumentado de eventos trombóticos.", "A síndrome nefrótica apresenta hematúria marcada e cilindros hemáticos como achados típicos na urina.", "Na síndrome nefrótica há anasarca, muitas vezes com início periorbitário."], "p": 1},{"a": 3, "t": "Neurocisticercose (T10 Q3)", "e": "Sobre a neurocisticercose, assinale a alternativa correta:", "o": ["A ingestão de carne suína mal cozida é a principal forma de transmissão da neurocisticercose humana.", "Crises epilépticas são mais comuns quando os cistos se localizam no parênquima cerebral.", "A forma parenquimatosa tende a evoluir com hipertensão intracraniana grave e hidrocefalia obstrutiva.", "O tratamento antiparasitário deve ser evitado em todos os casos, pois aumenta o risco de inflamação meníngea.", "Os exames sorológicos têm sensibilidade elevada em todas as formas, sendo suficientes para confirmar o diagnóstico."], "c": 1, "x": "Gabarito B. Carne suína = teníase (neurocisticercose vem dos OVOS, via fecal-oral); hidrocefalia é da forma VENTRICULAR; albendazol + corticoide no parasita ativo; “todos/todas” = pegadinha.", "r": "SP3 · Neurocisticercose", "p": 1},{"a": 1, "t": "Túbulo-intersticial (T10 Q4)", "e": "Sobre as doenças túbulo-intersticiais renais, assinale a alternativa correta:", "o": ["A eosinofilia e a eosinofilúria são achados sugestivos, especialmente nos quadros agudos por hipersensibilidade medicamentosa.", "Infecções, doenças autoimunes e causas mecânicas são as principais causas de doenças intersticiais renais agudas.", "Febre e exantema são encontrados na forma infecciosa exclusivamente.", "A biópsia renal é o exame padrão-ouro para o diagnóstico das doenças túbulo-intersticiais.", "Na doença intersticial aguda, os rins tendem a apresentar redução de tamanho e ecogenicidade aumentada ao ultrassom."], "c": 0, "x": "Gabarito A (deduzido pela correção). A causa mais comum é DROGA; febre + exantema + artralgia = tríade da forma alérgica; biópsia só em casos selecionados; rim pequeno e hiperecogênico = forma CRÔNICA.", "r": "SP1 · Nefrite túbulo-intersticial", "p": 1},{"a": 3, "t": "Meningite bacteriana (T10 Q5)", "e": "Sobre meningite bacteriana aguda, analise:", "o": ["I, III e V", "II e V", "III e IV", "III e V", "I, II e III"], "c": 3, "x": "Gabarito D (III e V). Glicose MUITO BAIXA na bacteriana; TC antes da punção se HIC (não “sempre”); Listeria = idosos, imunossuprimidos, gestantes.", "r": "SP3 · Meningites", "it": ["O LCR tipicamente apresenta glicose normal, pois a bactéria não consome glicose no espaço subaracnoideo.", "A punção lombar deve ser realizada sempre para determinar o agente etiológico e o tratamento mais indicado.", "A dexametasona pode ser iniciada antes ou junto do antibiótico, reduzindo complicações em casos de pneumococo.", "A Listeria monocytogenes é causa predominante de meningite em adultos jovens saudáveis.", "Além da meningite isolada e da meningococcemia, a doença meningocócica pode se manifestar em outras formas clínicas, como artrite, pericardite e uretrite."], "p": 1},{"a": 4, "t": "Lesão viral (T10 Q6)", "e": "Sobre os mecanismos de lesão celular induzidos por vírus e as doenças virais, assinale a alternativa correta:", "o": ["Os vírus utilizam o maquinário biossintético da célula infectada para produzir novas partículas virais, mas podem se replicar fora da célula hospedeira.", "A inibição da síntese de DNA/RNA celular é um mecanismo de lesão viral que contribui para morte celular.", "Nenhum vírus altera vias de apoptose; esse mecanismo é exclusivo de bactérias intracelulares.", "HIV, herpes simples (HSV) e HPV são exemplos de infecções virais crônicas persistentes.", "Alguns vírus oncogênicos transformam células hospedeiras principalmente por integrarem seu material genético ao DNA celular, mas esse processo não está associado à inibição de mecanismos de reparo do DNA."], "c": 1, "x": "Gabarito B. Vírus é intracelular OBRIGATÓRIO; alteração da apoptose É mecanismo viral; HSV é LATENTE (crônicos persistentes: HCV, HIV, HPV); oncogênese viral envolve sim inibição do reparo.", "r": "SP4 · Vírus", "p": 1},{"a": 2, "t": "Endocardite infecciosa (T10 Q7)", "e": "Analise as afirmativas sobre endocardite infecciosa:", "o": ["I, II e IV", "II, III e V", "I, III e IV", "I, II e III", "III, IV e V"], "c": 3, "x": "Gabarito D (I, II e III). Sopro novo/agravado TEM valor (critério clínico); no usuário de droga IV o lado mais acometido é o DIREITO (tricúspide).", "r": "SP2 · Endocardite infecciosa", "it": ["As vegetações infecciosas são formadas por fibrina, plaquetas, leucócitos e microrganismos aderidos ao endocárdio.", "Por sua localização e ausência de vascularização, as valvas cardíacas são particularmente vulneráveis a agressões hemodinâmicas e infecciosas.", "O grupo Streptococcus viridans é causa frequente de endocardite em valvas previamente lesadas ou deformadas.", "A presença de sopro novo ou agravado não tem valor diagnóstico, pois ocorre na minoria dos pacientes.", "Usuários de drogas injetáveis tendem a apresentar maior acometimento de valvas esquerdas, sobretudo mitral."], "p": 1},{"a": 5, "t": "Pênfigo vulgar (T10 Q8)", "e": "Sobre o pênfigo vulgar, assinale a alternativa correta:", "o": ["As bolhas são tensas, profundas e subepidérmicas, pouco suscetíveis à ruptura.", "O sinal de Nikolsky geralmente é negativo no pênfigo vulgar.", "Trata-se de uma bolha intraepidérmica causada por acantólise suprabasal.", "A imunofluorescência mostra depósitos granulares de IgA nas papilas dérmicas.", "Clinicamente, o acometimento de mucosas é raro e costuma ocorrer apenas em formas avançadas."], "c": 2, "x": "Gabarito C. Tensa/subepidérmica = penfigoide; Nikolsky é POSITIVO; IgA nas papilas = dermatite herpetiforme; mucosa oral é FREQUENTE e pode preceder a pele.", "r": "SP5 · Pênfigo vulgar", "p": 1},{"a": 5, "d": 1, "t": "Psoríase — imunologia (T10 Q9)", "e": "Explique os principais mecanismos imunológicos envolvidos na psoríase e relacione-os com pelo menos duas alterações clínicas/histológicas observadas nesse quadro.", "ans": "Ativação de células dendríticas e linfócitos T → produção de IL-23, IL-17 e TNF-α → inflamação cutânea → proliferação acelerada dos queratinócitos (renovação ≈ 3–5 dias em vez de 28), que não amadurecem → acúmulo de queratina.\nAlterações: (1) placas eritematosas bem delimitadas com escamas espessas, secas e prateadas; (2) sinal de Auspitz — sangramento puntiforme ao remover a escama, por adelgaçamento epidérmico suprapapilar e capilares dilatados superficiais. (Também vale: fenômeno de Koebner.)\nNão vale: “é autoimune” genérico, nem Anitschkow (é da miocardite reumática).", "r": "SP5 · Psoríase", "p": 1},{"a": 2, "d": 1, "t": "Critérios maiores de Jones (T10 Q10)", "e": "Cite e explique (de forma objetiva) os 5 critérios maiores de Jones para o diagnóstico da febre reumática.", "ans": "Cardite (clínica ou subclínica no eco com Doppler — pancardite, sobretudo valvulite mitral); artrite migratória de grandes articulações; nódulos subcutâneos (granulomatosos, sobre proeminências ósseas/tendões); coreia de Sydenham (movimentos involuntários, tardia); eritema marginado (tronco e raiz dos membros, não pruriginoso, centro claro). Diagnóstico: evidência de infecção estreptocócica + 2 maiores ou 1 maior + 2 menores.\nA aluna citou só 4 (faltou eritema marginado) e não explicou → 0,4.", "r": "SP2 · Febre reumática", "p": 1},{"a": 4, "d": 1, "t": "Príons (T10 Q11A)", "e": "Explique em 2 linhas o mecanismo de ação dos príons. Deve deixar claro por que causam dano e qual é o tecido/órgão mais acometido.", "ans": "Príon = proteína do hospedeiro mal dobrada (PrPSc), sem material genético, que induz a conversão da PrP normal (PrPc, gene PRNP) em forma anormal, numa reação em cadeia; o acúmulo causa disfunção e perda neuronal, com vacuolização do neurópilo e gliose. Órgão: sistema nervoso central (ex.: Creutzfeldt-Jakob).", "r": "SP4 · Príons", "p": 1},{"a": 5, "d": 1, "t": "Dermatite eczematosa crônica (T10 Q11B)", "e": "Liste 3 sinais/características clínicas que permitam o diagnóstico diferencial da dermatite eczematosa crônica.", "ans": "Liquenificação (linhas acentuadas e endurecidas); hiperqueratose com descamação; xerose e fissuras; (prurido persistente em ciclo; mais comum em mãos, punhos e regiões flexoras). Febre NÃO é característica.", "r": "SP5 · Dermatite eczematosa crônica", "p": 1},{"a": 3, "d": 1, "t": "Três casos (T10 Q12)", "e": "Indique a hipótese diagnóstica mais provável:\nCaso 1: 14 anos, urina “cor de Coca-Cola”, edema periorbitário e HAS 10 dias após faringoamigdalite não tratada; hematúria com cilindros hemáticos, proteinúria moderada, C3 reduzido.\nCaso 2: 37 anos, febre, cefaleia intensa e alteração comportamental aguda, desorientação e fala incoerente há 24 h, crises convulsivas e rebaixamento; TC normal, RM com hipersinal no lobo temporal; LCR com pleocitose linfocitária e proteínas discretamente elevadas.\nCaso 3: 28 anos, sinusite frontal recente, febre alta, cefaleia, piora da consciência e hemiparesia direita; TC com coleção crescentiforme no espaço subdural, desvio de linha média e captação periférica; sinais meníngeos; LCR normal.", "ans": "Caso 1: glomerulonefrite pós-estreptocócica (síndrome nefrítica).\nCaso 2: encefalite herpética (HSV-1) — “meningite viral” não pontuou.\nCaso 3: empiema subdural — “encefalite” não pontuou.", "r": "SP1/SP3 · Casos", "p": 1},{"a": 4, "t": "Príons", "e": "Sobre os príons, assinale a INCORRETA:", "o": ["São formas anormais de uma proteína do próprio hospedeiro.", "Não possuem DNA nem RNA.", "A doença de Creutzfeldt-Jakob pode ser esporádica, genética ou adquirida.", "A confirmação definitiva da doença de Creutzfeldt-Jakob é feita pelo RT-QuIC no líquor.", "A morfologia inclui vacuolização do neurópilo, perda neuronal e gliose."], "c": 3, "x": "O RT-QuIC apoia o diagnóstico PROVÁVEL; a confirmação definitiva é o tecido cerebral, em geral após o óbito.", "r": "SP4 · Creutzfeldt-Jakob"},{"a": 4, "t": "Doença priônica", "e": "Paciente de 62 anos com declínio cognitivo rapidamente progressivo em 3 meses, mioclonias e ataxia. RM com hipersinal cortical e nos núcleos da base. Hipótese mais provável:", "o": ["Doença de Alzheimer", "Doença de Creutzfeldt-Jakob", "Encefalite herpética", "Neurocisticercose", "Abscesso cerebral"], "c": 1, "x": "Demência rápida + mioclonias + hipersinal em córtex/núcleos da base = CJD, a doença priônica humana mais frequente.", "r": "SP4 · Creutzfeldt-Jakob"},{"a": 4, "t": "Tipos de infecção viral", "e": "Associe corretamente o tipo de infecção viral ao exemplo:", "o": ["Latente com reativação — HCV", "Crônica persistente — varicela-zóster", "Aguda e autolimitada — rotavírus", "Altamente letal — rinovírus", "Latente com reativação — HPV"], "c": 2, "x": "Agudas: resfriado, rotavírus, sarampo. Crônicas persistentes: HCV, HIV, HPV. Latentes: HSV, VZV. Letais: Ebola.", "r": "SP4 · Vírus"},{"a": 4, "t": "Vírus oncogênicos", "e": "Qual associação vírus → neoplasia está correta?", "o": ["EBV → câncer cervical", "HTLV-1 → linfoma de Burkitt", "HPV → câncer cervical", "HPV → leucemia de células T", "EBV → leucemia de células T"], "c": 2, "x": "HPV → câncer cervical · EBV → linfoma de Burkitt · HTLV-1 → leucemia de células T.", "r": "SP4 · Lesão viral"},{"a": 4, "t": "Efeito citopático", "e": "Formação de sincícios (fusão de células infectadas) é exemplo de efeito citopático típico de:", "o": ["Influenza", "Sarampo, HIV e VSR", "Raiva", "Rotavírus", "Ebola"], "c": 1, "x": "Sincícios: sarampo, HIV, VSR. Inclusões: HSV, CMV, raiva. Lise: influenza.", "r": "SP4 · Lesão viral"},{"a": 4, "t": "Micoplasma", "e": "O Mycoplasma pneumoniae é naturalmente resistente aos β-lactâmicos porque:", "o": ["Produz β-lactamase cromossômica", "Não possui parede celular", "Tem porinas fechadas", "É intracelular obrigatório", "Possui bomba de efluxo"], "c": 1, "x": "Sem parede de peptidoglicano → o alvo do β-lactâmico não existe; por isso também é pleomórfico e sensível a variações osmóticas.", "r": "SP4 · Micoplasma"},{"a": 4, "t": "Riquétsias", "e": "Sobre as riquétsias, assinale a correta:", "o": ["São gram-positivas de vida livre.", "Têm tropismo endotelial e causam vasculite, petéquias e febre maculosa.", "Todas dependem de vetor artrópode, inclusive a Coxiella.", "Replicam-se apenas no meio extracelular.", "São o menor organismo de vida livre."], "c": 1, "x": "Gram-negativas atípicas, intracelulares obrigatórias; Coxiella burnetii é transmitida por aerossol, sem vetor; o menor de vida livre é o micoplasma.", "r": "SP4 · Riquétsias"},{"a": 4, "t": "Toxinas bacterianas", "e": "Associe a toxina ao efeito:", "o": ["Toxina botulínica → espasmos musculares", "Toxina tetânica → paralisia flácida", "Enterotoxina do V. cholerae → diarreia intensa", "LPS → produzido e secretado por gram-positivas", "Toxina diftérica → enterotoxina"], "c": 2, "x": "Tetânica = espasmo; botulínica = paralisia flácida; LPS é endotoxina da PAREDE das gram-negativas; difteria = citotoxina.", "r": "SP4 · Lesão bacteriana"},{"a": 4, "t": "Choque séptico", "e": "Na sepse por gram-negativo, a vasoplegia refratária decorre principalmente de:", "o": ["Ação direta do LPS no miocárdio", "Excesso de óxido nítrico após liberação de citocinas via TLR4", "Perda de antitrombina III", "Liberação de IgE por mastócitos", "Bloqueio de receptores α pela endotoxina"], "c": 1, "x": "LPS → TLR4/MD2/CD14 no macrófago → TNF-α, IL-1, IL-6 → NO em excesso → vasoplegia, ↑ permeabilidade, hipoperfusão → CIVD → MODS.", "r": "SP4 · Choque séptico"},{"a": 4, "t": "Antraz", "e": "Sobre a exotoxina do Bacillus anthracis, assinale a correta:", "o": ["O fator do edema ativa uma protease que mata a célula.", "O antígeno protetor permite a entrada do fator letal e do fator do edema.", "O fator letal aumenta o AMPc.", "A forma cutânea é a mais grave.", "É um bacilo gram-negativo sem esporos."], "c": 1, "x": "PA = porta; LF = protease → morte; EF = ↑ AMPc → edema. Cutânea é a mais COMUM; pulmonar a mais GRAVE. Gram-positivo esporulado.", "r": "SP4 · Antraz"},{"a": 4, "t": "Resistência bacteriana", "e": "A perda da porina OprD em Pseudomonas aeruginosa confere resistência a carbapenêmicos por qual mecanismo?", "o": ["Inativação enzimática", "Alteração do sítio-alvo", "Redução da permeabilidade", "Efluxo ativo", "Alteração ribossomal"], "c": 2, "x": "Os 4 mecanismos: enzima (β-lactamase, KPC, AMEs) · alvo (PBP do MRSA, ribossomo, girase) · ↓ permeabilidade (porinas) · efluxo (MDR).", "r": "SP4 · Resistência"},{"a": 4, "t": "Resistência — alvo", "e": "A resistência do MRSA à meticilina se deve a:", "o": ["Produção de carbapenemase", "Alteração das PBPs", "Perda de porinas", "Bomba de efluxo", "Enzimas modificadoras de aminoglicosídeos"], "c": 1, "x": "MRSA = alteração do sítio-alvo (PBP alterada).", "r": "SP4 · Resistência"},{"a": 4, "t": "Fungos", "e": "Sobre os fungos, assinale a INCORRETA:", "o": ["São eucariontes com parede de quitina.", "O ergosterol da membrana é alvo de antifúngicos como o cetoconazol.", "O Cryptococcus tem cápsula que inibe a fagocitose.", "Dimórficos causam reação granulomatosa.", "Diabetes e antibioticoterapia prolongada protegem contra infecção fúngica."], "c": 4, "x": "Imunossupressão, ATB prolongado, diabetes e umidade/maceração são FATORES PREDISPONENTES.", "r": "SP4 · Fungos"},{"a": 4, "t": "Protozoários", "e": "Qual associação está correta?", "o": ["Leishmania — transmitida pelo Anopheles", "Doença de Chagas — sinal de Romaña na fase aguda", "Plasmodium — ciliado", "Giardia — esporozoário", "Toxoplasma — ameba"], "c": 1, "x": "Chagas: fezes do barbeiro; Romaña na aguda; IC e megacólon na crônica. Anopheles = malária; flebotomíneo = leishmaniose.", "r": "SP4 · Protozoários"},{"a": 5, "t": "Lesões elementares", "e": "Lesão elevada, sólida, com 2 cm de diâmetro é uma:", "o": ["Mácula", "Pápula", "Placa", "Vesícula", "Bolha"], "c": 2, "x": "Pápula < 1 cm; placa > 1 cm. Vesícula < 1 cm e bolha > 1 cm têm líquido.", "r": "SP5 · Lesões elementares"},{"a": 5, "t": "Eczema agudo × crônico", "e": "Assinale a correta:", "o": ["A espongiose é a principal característica da dermatite eczematosa crônica.", "A dermatite de contato alérgica é hipersensibilidade tipo I.", "A dermatite de contato irritativa decorre de dano direto por detergentes e solventes.", "A liquenificação é típica da forma aguda.", "A dermatite atópica predomina em superfícies extensoras."], "c": 2, "x": "Agudo = espongiose; crônico = liquenificação; contato alérgica = tipo IV (células T); atópica = flexoras.", "r": "SP5 · Dermatite eczematosa"},{"a": 5, "t": "Psoríase", "e": "Sobre a psoríase, assinale a INCORRETA:", "o": ["Envolve IL-23, IL-17 e TNF-α.", "A renovação epidérmica cai de ≈28 para 3–5 dias.", "O sinal de Auspitz é o surgimento de lesões em áreas de trauma.", "Lítio e betabloqueadores podem desencadear a doença.", "Associa-se a artrite, síndrome metabólica e maior risco cardiovascular."], "c": 2, "x": "Lesão em área de trauma = fenômeno de KOEBNER. Auspitz = sangramento puntiforme ao remover a escama.", "r": "SP5 · Psoríase"},{"a": 5, "t": "Líquen plano", "e": "Pápulas poligonais, planas, violáceas e pruriginosas nos punhos, com rede branca na mucosa oral, sugerem:", "o": ["Psoríase", "Líquen plano", "Pênfigo vulgar", "Dermatite herpetiforme", "Penfigoide bolhoso"], "c": 1, "x": "Líquen plano: infiltrado linfocitário na interface; estrias de Wickham na boca; pode dar alopecia no couro cabeludo.", "r": "SP5 · Líquen plano"},{"a": 5, "t": "Penfigoide bolhoso", "e": "Idoso de 78 anos com bolhas grandes e tensas no tronco e coxas, prurido intenso, Nikolsky negativo. A IFD deve mostrar:", "o": ["IgA granular nas papilas dérmicas", "IgG e C3 lineares na membrana basal", "Acantólise suprabasal sem depósitos", "Anticorpos anti-desmogleína-3", "Ausência de anticorpos (doença genética)"], "c": 1, "x": "Penfigoide: anti-BP180/BP230, subepidérmica, eosinófilos, IgG/C3 linear.", "r": "SP5 · Penfigoide bolhoso"},{"a": 5, "t": "Dermatite herpetiforme", "e": "Sobre a dermatite herpetiforme, assinale a correta:", "o": ["É causada pelo herpes simples.", "O anticorpo principal é IgG anti-desmogleína.", "Há depósito de IgA anti-transglutaminase epidérmica (TG3) na derme papilar, com neutrófilos.", "Predomina na mucosa oral.", "Não tem relação com glúten."], "c": 2, "x": "Celíaca na pele: glúten → TG2 → HLA-DQ2/DQ8 → IgA anti-TG3 → neutrófilos → microabscessos; vesículas agrupadas em cotovelos, joelhos, nádegas.", "r": "SP5 · Dermatite herpetiforme"},{"a": 5, "t": "Comparativo bolhosas", "e": "Qual característica é EXCLUSIVA do pênfigo vulgar entre as três bolhosas autoimunes?", "o": ["Bolha subepidérmica", "Nikolsky positivo", "Neutrófilos na derme papilar", "Associação com doença celíaca", "Prurido intenso"], "c": 1, "x": "Nikolsky + só no pênfigo (intraepidérmica, acantólise). Penfigoide e herpetiforme são subepidérmicas e Nikolsky −.", "r": "SP5 · Comparativo"},{"a": 5, "t": "Epidermólise bolhosa", "e": "Sobre a epidermólise bolhosa, assinale a correta:", "o": ["É autoimune e surge no idoso.", "Na forma juncional, a clivagem ocorre na derme superior.", "A forma distrófica recessiva grave tem risco de carcinoma espinocelular precoce.", "Tem cura com imunossupressores.", "Não acomete mucosas."], "c": 2, "x": "Genética, infância; simples = epiderme inferior, juncional = membrana basal, distrófica = derme superior, Kindler = várias; sem cura; pode pegar mucosas.", "r": "SP5 · Epidermólise bolhosa"},{"a": 5, "t": "Exantemas virais", "e": "Criança com febre alta por 3 dias que desaparece abruptamente, seguida de exantema rosado no tronco:", "o": ["Sarampo", "Rubéola", "Parvovírus B19", "HHV-6 (exantema súbito)", "Escarlatina"], "c": 3, "x": "Exantema súbito (roséola) = HHV-6. Parvovírus = face esbofeteada; rubéola = linfonodo retroauricular; sarampo = Koplik.", "r": "SP5 · Exantemas"},{"a":1,"t":"Nefrítica × nefrótica","e":"Analise as assertivas sobre as síndromes glomerulares:","it":["Na síndrome nefrítica há hematúria glomerular dismórfica, com cilindros hemáticos.","Na síndrome nefrótica a proteinúria é moderada, inferior a 3,5 g/dia.","O maior risco de trombose na síndrome nefrótica decorre da perda urinária de antitrombina III.","A hiperlipidemia da síndrome nefrótica decorre da redução da síntese hepática de lipoproteínas.","A GN pós-estreptocócica é o exemplo típico de nefrítica, e a nefropatia membranosa, de nefrótica."],"o":["I, II e III","I, III e V","II, IV e V","I, III, IV e V","III e V"],"c":1,"x":"II é falsa: na nefrótica a proteinúria é MACIÇA (> 3,5 g/dia). IV é falsa: a síntese hepática de lipoproteínas AUMENTA (compensatória) — é exatamente a troca de uma palavra que a professora gosta de fazer.","r":"SP1 · Síndrome nefrótica"},{"a":1,"t":"GN pós-estreptocócica","e":"Menino de 8 anos chega com urina “cor de Coca-Cola”, edema periorbitário e PA de 140/90 mmHg. A mãe conta que há 3 semanas ele teve dor de garganta com placas. Qual conjunto de exames é o mais esperado?","o":["C3 ↓, C4 normal e ASLO positiva","C3 ↓, C4 ↓ e anti-DNAds positivo","Proteinúria de 6 g/dia, lipidúria e cruzes de Malta","Anticorpo anti-PLA2R positivo","Eosinofilia e eosinofilúria"],"c":0,"x":"“C3 ↓ + ASLO + → pense em GN pós-estreptocócica” (slide de dicas rápidas). C3 e C4 baixos apontam para lúpus/GNMP tipo I; anti-PLA2R é da membranosa; eosinofilúria é da nefrite intersticial por droga.","r":"SP1 · Diagnóstico das GN"},{"a":1,"t":"Glomerulonefrites","e":"Assinale a alternativa INCORRETA sobre as glomerulonefrites:","o":["A biópsia renal é o padrão-ouro para a classificação, pois define o tipo histológico.","Na síndrome de Goodpasture, autoanticorpos anti-membrana basal glomerular e alveolar causam hematúria e hemoptise.","As GN pauci-imunes não têm depósitos imunes visíveis e decorrem da ativação de neutrófilos por ANCA.","A nefropatia por IgA (doença de Berger) manifesta-se classicamente por proteinúria maciça e anasarca.","A nefrite lúpica é exemplo de glomerulopatia com padrão misto."],"c":3,"x":"A nefropatia por IgA tem padrão NEFRÍTICO: depósito de IgA após infecções respiratórias, causando hematúria recorrente.","r":"SP1 · Padrão de cada glomerulopatia"},{"a":1,"t":"Glomerulopatias nefróticas","e":"Assinale a associação CORRETA:","o":["Doença de lesões mínimas — adultos, anticorpo anti-PLA2R","Glomeruloesclerose segmentar e focal — pode recidivar após transplante","Glomerulopatia membranosa — depósitos subendoteliais, típica de crianças","GN membranoproliferativa — depósito de IgA no mesângio","Glomerulopatias secundárias — o lúpus é a causa mais comum"],"c":1,"x":"Lesões mínimas = fusão dos podócitos, crianças. Membranosa = imunocomplexos SUBEPITELIAIS, anti-PLA2R, adultos. GNMP = ativação anormal do complemento e duplicação da MB. Nas secundárias, a causa mais comum é o DIABETES.","r":"SP1 · Padrão nefrótico"},{"a":1,"t":"Complemento","e":"Uma criança tratada como GN pós-estreptocócica mantém C3 baixo 10 semanas depois. Segundo a aula, qual hipótese deve ser avaliada?","o":["Nefropatia por IgA","GN membranoproliferativa ou lúpus","Doença de lesões mínimas","Nefrite intersticial por droga","Evolução normal da GN pós-estreptocócica"],"c":1,"x":"“C3 persistentemente ↓ > 8 semanas → avaliar GNMP ou lúpus.” Na pós-estreptocócica o complemento volta ao normal.","r":"SP1 · Dicas rápidas"},{"a":1,"t":"Nefrite túbulo-intersticial","e":"Sobre as doenças intersticiais renais, analise:","it":["Drogas são a causa mais comum, por reação de hipersensibilidade.","Na forma alérgica, a tríade clássica é febre, exantema e artralgia.","É típica a leucocitúria com bacteriúria abundante.","Pode haver anemia precoce, antes da queda importante da TFG.","Na fase crônica, a USG mostra rins aumentados com córtex hipoecogênico."],"o":["I, II e IV","I, III e V","II, III e IV","I, II, IV e V","II e V"],"c":0,"x":"III: é leucocitúria SEM bacteriúria. V: na fase crônica os rins são DIMINUÍDOS com córtex HIPERecogênico (aumentados/normais é a fase aguda).","r":"SP1 · Doenças túbulo-intersticiais"},{"a":1,"t":"Caso — nefrite intersticial","e":"Mulher de 52 anos, em uso de omeprazol há 6 semanas, apresenta febre, rash difuso e creatinina que subiu de 0,9 para 2,4 mg/dL. EAS com leucocitúria estéril e eosinofilúria. Hipótese e conduta principal:","o":["GN pós-estreptocócica; penicilina","Nefrite túbulo-intersticial aguda por droga; suspender o omeprazol","Síndrome nefrótica; corticoide e estatina","Pielonefrite aguda; antibiótico EV","DRC estágio G3b; preparar para diálise"],"c":1,"x":"IBP está na lista de drogas da aula. Eosinofilúria + leucocitúria sem bacteriúria + tríade alérgica = nefrite TI aguda. Primeira medida: retirar o agente causador; corticoide só em casos graves.","r":"SP1 · Doenças túbulo-intersticiais"},{"a":1,"t":"DRC — definição","e":"Assinale a alternativa CORRETA sobre o diagnóstico de doença renal crônica:","o":["Exige TFG < 60 mL/min/1,73 m² OU marcador de lesão renal, persistentes por pelo menos 3 meses.","Basta uma única medida de TFG < 60 mL/min/1,73 m².","Só pode ser diagnosticada se houver albuminúria > 300 mg/g.","Exige TFG < 15 mL/min/1,73 m².","É confirmada pelo achado de rins aumentados à USG."],"c":0,"x":"Duas ou mais medidas de TFG < 60 com 3 meses de intervalo, OU marcador persistente de lesão (albuminúria > 30 mg/g, hematúria dismórfica, alteração estrutural) mesmo com TFG normal.","r":"SP1 · DRC"},{"a":1,"t":"KDIGO","e":"Paciente com TFG estimada de 38 mL/min/1,73 m² há 5 meses. Pela KDIGO 2012, o estágio é:","o":["G2","G3a","G3b","G4","G5"],"c":2,"x":"G3a = 45–59; G3b = 30–44; G4 = 15–29.","r":"SP1 · KDIGO"},{"a":1,"t":"DRC — quadro","e":"Sobre o quadro clínico da DRC, analise:","it":["Nas fases iniciais costuma ser assintomática, só com azotemia.","A anemia típica é microcítica e hipocrômica.","Há doença mineral óssea, com hipocalcemia, hiperfosfatemia e hiperparatireoidismo secundário.","Podem ocorrer hipercalemia e acidose metabólica.","No Brasil, a hipertensão é a causa mais comum de DRC."],"o":["I, II e III","I, III e IV","II, III e V","I, IV e V","III, IV e V"],"c":1,"x":"A anemia da DRC é NORMOcítica e NORMOcrômica. A principal causa no Brasil e no mundo é o DIABETES (~40%); a HAS é a 2ª (~25%).","r":"SP1 · DRC — quadro clínico"},{"a":1,"t":"Estimativa da TFG","e":"Sobre as fórmulas de estimativa da função renal, assinale a INCORRETA:","o":["A Cockcroft-Gault usa o peso corporal.","A CKD-EPI 2021 eliminou a raça como variável.","A Cockcroft-Gault expressa o resultado em mL/min/1,73 m².","A CKD-EPI 2021 é hoje a mais recomendada em adultos.","A CKD-EPI 2009 incluía raça como variável."],"c":2,"x":"A Cockcroft-Gault estima a depuração de creatinina em mL/min, sem corrigir pela superfície corporal. As CKD-EPI é que dão mL/min/1,73 m².","r":"SP1 · Como estimar a TFG"},{"a":1,"t":"Diálise","e":"Todas são indicações de início de diálise na DRC, EXCETO:","o":["Uremia refratária","Hipercalemia refratária","Hipervolemia refratária","Acidose metabólica persistente","TFG de 25 mL/min/1,73 m² em paciente assintomático"],"c":4,"x":"TFG 15–29 = G4: preparar para TRS. A diálise costuma iniciar com TFG < 10 ou complicações refratárias.","r":"SP1 · Indicações de diálise"},{"a":1,"d":1,"t":"Discursiva — nefrótica","e":"Mulher de 40 anos com edema generalizado, proteinúria de 6 g/24 h, albumina de 2,1 g/dL e colesterol elevado.\nA) Qual a síndrome e qual o exemplo típico citado em aula?\nB) Explique a fisiopatologia do edema e da hiperlipidemia.","ans":"A) Síndrome nefrótica (proteinúria > 3,5 g/dia + hipoalbuminemia < 3,0 g/dL + edema + hiperlipidemia). Exemplo típico: nefropatia (GN) membranosa.\nB) Lesão podocitária → perda da barreira de filtração → proteinúria maciça → hipoalbuminemia → ↓ pressão oncótica plasmática → edema (anasarca). O fígado aumenta a síntese de proteínas de forma compensatória, incluindo lipoproteínas (LDL, VLDL) → hiperlipidemia e lipidúria.","r":"SP1 · Síndrome nefrótica"},{"a":2,"t":"Febre reumática","e":"Sobre a febre reumática, analise:","it":["É uma complicação supurativa da faringite estreptocócica.","Ocorre geralmente 2 a 4 semanas após a faringite.","Anticorpos contra a proteína M reagem de forma cruzada com antígenos do coração, cérebro, pele e articulações.","A ASLO elevada, isoladamente, confirma o diagnóstico.","O tratamento da faringite iniciado até o 9º dia previne a febre reumática."],"o":["I, II e III","II, III e V","II, IV e V","I, III e IV","III e V"],"c":1,"x":"I: é NÃO supurativa (imunomediada). IV: ASLO indica infecção prévia; isolada NÃO confirma FR.","r":"SP2 · Febre reumática"},{"a":2,"t":"Critérios de Jones","e":"Menina de 11 anos, 3 semanas após amigdalite, com artrite migratória de joelhos e tornozelos, febre de 38,5 °C, VHS de 70 mm/h e ASLO elevada. Ecocardiograma normal. Pelos critérios de Jones (2015):","o":["Não preenche: são necessários 2 critérios maiores.","Preenche: 1 critério maior (artrite) + 2 menores (febre e VHS elevado).","Preenche: artrite e artralgia contam como 1 maior + 1 menor.","Não preenche: a ASLO não é aceita como evidência de infecção.","Só preenche se houver PR prolongado no ECG."],"c":1,"x":"Infecção estreptocócica recente (ASLO) + 1 maior + 2 menores. Artralgia não pode ser contada junto com artrite.","r":"SP2 · Critérios de Jones"},{"a":2,"t":"Critérios maiores","e":"Assinale a INCORRETA sobre os critérios de Jones:","o":["A coreia de Sydenham é o sinal neurológico patognomônico da FR e surge tardiamente.","O eritema marginado é pruriginoso e localiza-se nas extremidades distais dos membros.","Os nódulos subcutâneos são áreas de inflamação granulomatosa sobre proeminências ósseas e tendões.","A cardite subclínica é diagnosticada por ecocardiograma com Doppler.","O PR prolongado não conta como critério menor quando a cardite já é critério maior."],"c":1,"x":"O eritema marginado é NÃO pruriginoso, de bordas onduladas e centro claro, no TRONCO e na parte proximal dos membros.","r":"SP2 · Critérios de Jones"},{"a":2,"t":"Pancardite reumática","e":"Assinale a alternativa CORRETA sobre a pancardite reumática:","o":["A lesão típica da miocardite é o corpúsculo de Aschoff, com centro fibrinoide e células de Anitschkow.","As vegetações da endocardite reumática são friáveis, volumosas e repletas de bactérias.","A valva mais acometida é a aórtica, seguida da mitral.","A insuficiência cardíaca da fase aguda deve-se principalmente à miocardite.","A pericardite é a manifestação cardíaca mais frequente."],"c":0,"x":"Vegetações reumáticas são pequenas e ESTÉREIS. Mitral > aórtica. A IC aguda relaciona-se principalmente à REGURGITAÇÃO valvar (mitral). A endocardite (valvulite) é a principal manifestação; a pericardite é menos frequente.","r":"SP2 · Pancardite reumática"},{"a":2,"t":"Histologia","e":"Na lâmina de miocárdio de uma criança com febre reumática, observam-se macrófagos com núcleo central e cromatina em fita ondulada, com aspecto de “lagarta” em corte longitudinal e “olho de coruja” em corte transversal. Essas células são:","o":["Células de Langhans","Células de Anitschkow","Células de Reed-Sternberg","Células epitelioides do granuloma tuberculoso","Células espumosas"],"c":1,"x":"Células de Anitschkow = macrófagos ativados do corpúsculo de Aschoff.","r":"SP2 · Miocardite reumática"},{"a":2,"t":"Pericardite","e":"Na autópsia, o pericárdio apresenta exsudato fibrinoso com aspecto de “pão com manteiga”. Isso é característico de:","o":["Pericardite purulenta da endocardite infecciosa","Pericardite fibrinosa da febre reumática","Pericardite urêmica da DRC","Tamponamento por hemopericárdio","Miocardite chagásica crônica"],"c":1,"x":"A pericardite reumática pode ser fibrinosa: “coração em pão com manteiga”. Clínica: dor torácica e atrito pericárdico.","r":"SP2 · Pericardite reumática"},{"a":2,"t":"Estenose mitral","e":"Sobre a estenose mitral reumática, analise:","it":["A fusão das comissuras dá o aspecto de “boca de peixe”.","O sopro típico é sistólico ejetivo.","Há estalido de abertura mitral.","A obstrução ao esvaziamento do átrio esquerdo leva a hipertensão pulmonar, dispneia e fibrilação atrial.","As cordas tendíneas ficam longas e finas."],"o":["I, II e III","I, III e IV","II, IV e V","I, IV e V","III, IV e V"],"c":1,"x":"O sopro é DIASTÓLICO (ruflar). As cordas ficam CURTAS e ESPESSAS.","r":"SP2 · Estenose mitral"},{"a":2,"t":"Endocardite — agente","e":"Homem de 28 anos, usuário de drogas injetáveis, com febre alta, calafrios e piora rápida há 4 dias. Ecocardiograma mostra vegetação volumosa na tricúspide. O agente mais provável é:","o":["Streptococcus do grupo viridans","Staphylococcus aureus","Estafilococo coagulase-negativo","Enterococcus faecalis","Streptococcus pyogenes"],"c":1,"x":"Droga IV → S. aureus: curso agudo e destrutivo, ataca valvas normais; no usuário de droga injetável a EI é mais comum à DIREITA.","r":"SP2 · Endocardite infecciosa"},{"a":2,"t":"Endocardite subaguda","e":"Mulher de 55 anos com estenose mitral reumática conhecida apresenta febre baixa, perda de peso e astenia há 6 semanas, iniciadas após extração dentária. Qual a forma e o agente mais prováveis?","o":["Aguda — S. aureus","Subaguda — Streptococcus do grupo viridans","Aguda — Enterococcus","Subaguda — estafilococo coagulase-negativo","Aguda — fungos"],"c":1,"x":"Viridans = microbiota oral, curso subagudo, valvas previamente alteradas (ex.: doença reumática).","r":"SP2 · Endocardite infecciosa"},{"a":2,"t":"Sinais periféricos da EI","e":"Assinale a INCORRETA sobre as manifestações da endocardite infecciosa:","o":["Os nódulos de Osler são dolorosos e localizam-se nos dedos.","As lesões de Janeway são dolorosas e localizam-se nas polpas digitais.","As manchas de Roth localizam-se na retina.","Na endocardite esquerda, os êmbolos vão para cérebro, rins e baço.","Podem ocorrer hemorragias em lasca nas unhas."],"c":1,"x":"Janeway = lesões INDOLORES em PALMAS e PLANTAS (fenômeno vascular). Doloroso nos dedos é o Osler (imunológico).","r":"SP2 · Manifestações da EI"},{"a":2,"t":"Duke–ISCVID 2023","e":"Segundo os critérios de Duke–ISCVID 2023, a endocardite é DEFINIDA por critérios clínicos quando há:","o":["1 maior + 1 menor","2 maiores, OU 1 maior + 3 menores, OU 5 menores","1 maior + 2 menores, OU 4 menores","3 maiores","Hemocultura positiva em qualquer número de amostras"],"c":1,"x":"2 maiores · 1 maior + 3 menores · 5 menores.","r":"SP2 · Critérios de Duke"},{"a":2,"t":"Duke — classificação","e":"Nos critérios de Duke–ISCVID 2023, as lesões de Janeway entram como:","o":["Critério maior microbiológico","Critério menor — fenômeno vascular","Critério menor — fenômeno imunológico","Critério maior de imagem","Não fazem parte dos critérios"],"c":1,"x":"Vasculares: embolização arterial, infartos pulmonares sépticos, Janeway. Imunológicos: Osler, Roth, GN por imunocomplexos.","r":"SP2 · Critérios de Duke"},{"a":2,"t":"Miocardite","e":"Sobre a miocardite, analise:","it":["O coxsackie B é uma das etiologias virais.","ECG e troponina normais excluem o diagnóstico.","A ressonância cardíaca tem papel central na caracterização da inflamação.","A biópsia endomiocárdica deve ser feita em todos os casos.","A doxorrubicina é causa de miocardite tóxica."],"o":["I, II e III","I, III e V","II, IV e V","I, IV e V","III e V"],"c":1,"x":"ECG e troponina normais NÃO excluem miocardite (asterisco do slide). Biópsia só em situações selecionadas, quando muda a conduta.","r":"SP2 · Miocardite"},{"a":2,"t":"Miocardite chagásica","e":"Sobre a patogênese da miocardite chagásica, assinale a CORRETA:","o":["O T. cruzi permanece extracelular, na forma tripomastigota, sem invadir os miócitos.","A forma amastigota, intracelular e sem flagelo, multiplica-se nos miócitos; a persistência do parasito e o mimetismo molecular levam à lesão crônica e fibrose.","A fase aguda caracteriza-se por infiltrado predominantemente eosinofílico sem necrose.","A lesão crônica é causada apenas pela ação direta do parasito, sem autoimunidade.","A miocardite chagásica não evolui para fibrose."],"c":1,"x":"Invasão → amastigota intracelular → inflamação aguda (infiltrado linfocitário + necrose) → persistência + autoimunidade (mimetismo) → fibrose.","r":"SP2 · Miocardite — patogênese"},{"a":2,"d":1,"t":"Discursiva — febre reumática","e":"Menino de 10 anos, 3 semanas após faringite não tratada, apresenta artrite migratória e sopro mitral novo.\nA) Qual o mecanismo patogênico da doença?\nB) Como se previne a progressão da lesão valvar?","ans":"A) Febre reumática: mimetismo molecular — anticorpos contra a proteína M do S. pyogenes reagem de forma cruzada com antígenos do coração (pancardite), articulações, SNC e pele.\nB) Profilaxia secundária com penicilina, que reduz as recorrências da FR e o agravamento da lesão valvar. (A primária é tratar a faringite até o 9º dia.)","r":"SP2 · Febre reumática"},{"a":2,"d":1,"t":"Discursiva — vegetações","e":"A) Cite a composição de uma vegetação na endocardite infecciosa.\nB) Diferencie as vegetações da febre reumática das da endocardite infecciosa.","ans":"A) Fibrina + plaquetas + leucócitos + microrganismos.\nB) FR (fase aguda): vegetações pequenas e ESTÉREIS (não bacterianas) nas bordas das cúspides, com células inflamatórias. EI: vegetações infecciosas, FRIÁVEIS, volumosas e destrutivas, com erosões/abscessos e desprendimento frequente de êmbolos.","r":"SP2 · Vegetações"},{"a":3,"t":"Classificação","e":"Assinale a alternativa CORRETA sobre a classificação das infecções do SNC:","o":["O empiema subdural é uma coleção purulenta entre a dura-máter e a aracnoide, sem acometer diretamente o parênquima.","A meningite é a inflamação da dura-máter.","A encefalite acomete primariamente as leptomeninges.","O abscesso cerebral é uma coleção purulenta difusa, sem cápsula.","O termo meningoencefalite define o agente etiológico."],"c":0,"x":"Meningite = pia + aracnoide (leptomeninges). Encefalite = parênquima. Abscesso = coleção ENCAPSULADA e localizada. Meningoencefalite é descritor anatômico, não define agente.","r":"SP3 · Classificação"},{"a":3,"t":"Etiologias de meningite","e":"Assinale a associação INCORRETA:","o":["Listeria monocytogenes — idosos e imunossuprimidos","Streptococcus pneumoniae — adultos, etilistas e esplenectomizados","Cryptococcus neoformans — pacientes com HIV","Haemophilus influenzae — idosos imunossuprimidos","Neisseria meningitidis — jovens e surtos"],"c":3,"x":"H. influenzae = crianças NÃO VACINADAS. Lembrete: o baço defende contra encapsuladas (meningococo, pneumococo, H. influenzae).","r":"SP3 · Etiologias"},{"a":3,"t":"LCR — bacteriana","e":"LCR: aspecto turvo, 1.200 células/mm³ com 90% de neutrófilos, proteína de 220 mg/dL e glicose de 18 mg/dL (glicemia 100 mg/dL). A etiologia mais provável é:","o":["Viral","Bacteriana","Fúngica","Tuberculosa","Encefalite herpética"],"c":1,"x":"Turvo + neutrófilos + proteína ↑↑ + glicose muito baixa (< 40 ou < 2/3 da glicemia) = bacteriana.","r":"SP3 · LCR"},{"a":3,"t":"LCR — tuberculosa","e":"Homem de 40 anos com febre baixa, sudorese noturna e perda de peso há 3 semanas, evolui com sonolência e diplopia por paralisia do VI par. LCR claro, 250 células (linfócitos), proteína 180 mg/dL, glicose 25 mg/dL. Hipótese:","o":["Meningite viral","Meningite bacteriana aguda","Meningite tuberculosa","Encefalite herpética","Abscesso cerebral"],"c":2,"x":"Subaguda + sintomas constitucionais + pares III/VI (vasculite basilar) + LCR linfocítico com proteína ↑↑ e glicose ↓↓ = TB.","r":"SP3 · Meningite tuberculosa"},{"a":3,"t":"Tríade clássica","e":"Na descrição clássica acadêmica, a tríade da meningite bacteriana aguda é:","o":["Febre, cefaleia e vômitos","Febre, rigidez de nuca e alteração do estado mental","Cefaleia, fotofobia e petéquias","Rigidez de nuca, Kernig e Brudzinski","Febre, convulsão e déficit focal"],"c":1,"x":"A cefaleia é muito frequente e usada na suspeita, mas a tríade acadêmica inclui a ALTERAÇÃO DO ESTADO MENTAL.","r":"SP3 · Quadro clínico"},{"a":3,"t":"TC antes da punção","e":"Todas as situações abaixo indicam TC de crânio antes da punção lombar, EXCETO:","o":["Rebaixamento do nível de consciência","Papiledema","Crise convulsiva","Febre alta isolada","Vômitos em jato"],"c":3,"x":"TC antes se sinais de HIC (rebaixamento, vômitos em jato, papiledema, convulsões, cefaleia intensa): a retirada de LCR com HIC pode provocar herniação.","r":"SP3 · Punção lombar"},{"a":3,"t":"Tratamento empírico","e":"Gestante de 30 anos com suspeita de meningite bacteriana. O esquema empírico indicado em aula é:","o":["Ceftriaxona + vancomicina","Ceftriaxona + vancomicina + ampicilina","Vancomicina + meropenem","Aciclovir isolado","Penicilina cristalina isolada"],"c":1,"x":"> 50 anos, imunodeprimido OU gestante: acrescentar ampicilina para cobrir Listeria.","r":"SP3 · Tratamento da meningite"},{"a":3,"t":"Dexametasona","e":"Na meningite bacteriana, a dexametasona iniciada antes ou junto com o antibiótico tem benefício demonstrado principalmente na infecção por:","o":["Neisseria meningitidis","Streptococcus pneumoniae","Listeria monocytogenes","Haemophilus influenzae em adultos","Cryptococcus neoformans"],"c":1,"x":"Slide: “Dexametasona pode ser iniciada antes ou junto com antibióticos → benefício em pneumococo”.","r":"SP3 · Tratamento da meningite"},{"a":3,"t":"Meningococcemia","e":"Sobre a patogênese das lesões da meningococcemia, analise:","it":["O LPS é reconhecido por TLR-4, liberando TNF-α, IL-1 e IL-6.","O pilus tipo IV permite a adesão ao endotélio e a formação de microcolônias.","Na CIVD há aumento do fibrinogênio e encurtamento do tempo de protrombina.","O consumo de plaquetas e fatores gera fenômenos trombóticos e hemorrágicos simultâneos.","A sequela mais comum é a perda auditiva."],"o":["I, II e III","I, II e IV","II, III e V","I, IV e V","III e IV"],"c":1,"x":"III: na CIVD o fibrinogênio CAI e o TP ALARGA (consumo) — mesma pegadinha da prova de Fisio. V: a complicação mais comum são as CICATRIZES/necrose das lesões purpúricas; perda auditiva = 4–10%.","r":"SP3 · Doença meningocócica"},{"a":3,"t":"Waterhouse-Friderichsen","e":"A síndrome de Waterhouse-Friderichsen, forma grave da doença meningocócica, corresponde a:","o":["Necrose hemorrágica das adrenais","Infarto hemorrágico da hipófise","Trombose dos seios venosos","Hemorragia alveolar difusa","Necrose tubular aguda"],"c":0,"x":"Destruição hemorrágica das glândulas adrenais.","r":"SP3 · Doença meningocócica"},{"a":3,"t":"Meningite tuberculosa","e":"Assinale a INCORRETA sobre a meningite tuberculosa:","o":["Os focos de Rich são granulomas latentes nas leptomeninges que, ao romper no espaço subaracnóideo, liberam bacilos.","A disseminação é hematogênica a partir de foco pulmonar.","Os sinais meníngeos surgem precocemente, nas primeiras horas.","A imagem pode mostrar realce meníngeo basal e hidrocefalia comunicante.","O tratamento é RIPE por no mínimo 9–12 meses, com corticoide adjuvante."],"c":2,"x":"Instalação SUBAGUDA; os sinais meníngeos aparecem TARDIAMENTE.","r":"SP3 · Meningite tuberculosa"},{"a":3,"t":"Encefalite herpética","e":"Mulher de 35 anos com febre, cefaleia, confusão, comportamento bizarro e crise convulsiva há 2 dias. RM: hipersinal em lobo temporal esquerdo. LCR claro, linfocítico, glicose normal. A conduta imediata é:","o":["Aguardar o PCR para HSV-1 antes de tratar","Iniciar aciclovir EV 10 mg/kg 8/8 h imediatamente","Ceftriaxona + vancomicina isoladas","Albendazol + corticoide","Drenagem neurocirúrgica"],"c":1,"x":"Aciclovir EV 10 mg/kg 8/8 h por 14–21 dias, início IMEDIATO, mesmo antes do PCR. O PCR para HSV-1 no LCR confirma.","r":"SP3 · Encefalite herpética"},{"a":3,"t":"Por que o lobo temporal?","e":"A predileção da encefalite herpética pelo lobo temporal medial e inferior explica-se por:","o":["Disseminação hematogênica a partir da orofaringe","Reativação do vírus latente no gânglio trigeminal, que se propaga ao cérebro","Contiguidade com o seio frontal","Maior vascularização do lobo temporal","Ruptura de focos de Rich"],"c":1,"x":"Reativação do HSV-1 latente no gânglio trigeminal.","r":"SP3 · Encefalite herpética"},{"a":3,"t":"Abscesso cerebral","e":"Assinale a INCORRETA sobre o abscesso cerebral:","o":["Na RM com contraste aparece como lesão com realce em anel.","A restrição à difusão ajuda a diferenciar de neoplasias.","A febre pode estar ausente em até 50% dos casos.","A punção lombar é o exame de escolha para confirmar o diagnóstico.","A drenagem cirúrgica é indicada em lesões > 2,5 cm."],"c":3,"x":"A punção lombar é CONTRAINDICADA (risco de herniação).","r":"SP3 · Abscesso cerebral"},{"a":3,"t":"Abscesso — origem","e":"Paciente com sinusite frontal crônica desenvolve abscesso cerebral. A localização mais provável é:","o":["Lobo temporal","Cerebelo","Lobo frontal","Lobo occipital","Lesões múltiplas"],"c":2,"x":"Sinusite → lobo FRONTAL. Otite/mastoidite → temporal e cerebelo. Imunossuprimido → lesões múltiplas.","r":"SP3 · Abscesso cerebral"},{"a":3,"t":"Neurocisticercose","e":"Assinale a INCORRETA sobre a neurocisticercose:","o":["É causada pela forma larvária (cisticerco) da Taenia solium.","É adquirida pela ingestão de ovos, por via fecal-oral.","É adquirida pelo consumo de carne suína mal cozida.","A forma parenquimatosa é a mais comum e cursa com crises convulsivas.","É a principal causa de epilepsia adquirida em regiões endêmicas."],"c":2,"x":"Carne suína mal cozida (com cisticerco) causa TENÍASE (verme adulto no intestino), não neurocisticercose.","r":"SP3 · Neurocisticercose"},{"a":3,"t":"Estágios do cisticerco","e":"Na TC, um cisto com realce anelar e edema perilesional, em paciente com crises convulsivas recentes, corresponde ao estágio:","o":["Vesicular","Coloidal","Granular-nodular","Calcificado","Escólex viável sem inflamação"],"c":1,"x":"Coloidal = maior reação inflamatória, realce anelar + edema, crises comuns. Vesicular = cisto com escólex sem edema/realce.","r":"SP3 · Neurocisticercose"},{"a":3,"t":"Forma ventricular","e":"A neurocisticercose de localização ventricular manifesta-se principalmente por:","o":["Crises convulsivas focais isoladas","Hidrocefalia, hipertensão intracraniana e crises de Bruns","Perda visual","Déficits motores e sensitivos medulares","Meningite crônica e AVE"],"c":1,"x":"Parenquimatosa → crises; ventricular → hidrocefalia/HIC/Bruns; subaracnóidea → meningite crônica, vasculite, AVE; espinhal → déficits; ocular → perda visual.","r":"SP3 · Neurocisticercose"},{"a":3,"d":1,"t":"Discursiva — meningococcemia","e":"Adolescente de 16 anos com febre alta, rigidez de nuca e petéquias que evoluem para púrpura extensa; há retorno de sangue pela sonda nasogástrica.\nA) Qual complicação hematológica ocorreu e qual o seu mecanismo?\nB) Cite duas sequelas da doença meningocócica.","ans":"A) CIVD: o LPS (via TLR-4) e as citocinas (TNF-α, IL-1, IL-6) lesam o endotélio e ativam a coagulação de forma sistêmica e desregulada → formação excessiva de trombina e fibrina → microtrombos (isquemia) + consumo de plaquetas e fatores → hemorragias difusas (púrpura, sangramento pela SNG).\nB) Necrose/cicatrizes cutâneas (a mais comum, com enxertos), amputações (~2%), perda auditiva (4–10%), sequelas neurológicas (~7%); óbito ~10%.","r":"SP3 · Doença meningocócica"},{"a":3,"d":1,"t":"Discursiva — convulsão na NCC","e":"A) Explique por que a neurocisticercose parenquimatosa causa crises convulsivas.\nB) Qual o tratamento quando o parasita está ativo?","ans":"A) Os cistos ficam próximos a regiões corticais epileptogênicas; quando o parasita morre (naturalmente ou pelo tratamento) há inflamação local que altera o ambiente neuronal e favorece hiperexcitabilidade; nas fases tardias, cicatrizes e calcificações viram focos epilépticos permanentes.\nB) Albendazol (às vezes praziquantel) + corticoide para reduzir a inflamação durante a destruição do cisto; anticonvulsivantes para as crises.","r":"SP3 · Neurocisticercose"},{"a":3,"d":1,"t":"Discursiva — LCR","e":"A) Diferencie o LCR da meningite bacteriana e da viral quanto a aspecto, célula predominante e glicose.\nB) Quando se deve fazer TC antes da punção e por quê?","ans":"A) Bacteriana: turvo, neutrófilos, glicose muito baixa (< 40 mg/dL ou < 2/3 da glicemia), proteína ↑↑. Viral: claro, linfócitos, glicose normal ou discretamente ↓, proteína normal ou ↑ leve.\nB) Na presença de sinais de HIC (rebaixamento, vômitos em jato, papiledema, convulsões, cefaleia intensa), porque a retirada súbita de LCR pode descompensar a pressão entre compartimentos e provocar herniação cerebral.","r":"SP3 · Meningites"},{"a":0,"p":1,"t":"CIVD na sepse (T11 Q6)","e":"Coagulação Intravascular Disseminada (CIVD) é uma complicação grave da sepse. Analise as assertivas:","it":["Citocinas pró-inflamatórias, como o TNF-α e a IL-1, desencadeiam lesão no endotélio vascular e ativam a cascata de coagulação, culminando na formação disseminada de trombos microvasculares.","A fisiopatologia da CIVD envolve o consumo intenso de plaquetas e fatores de coagulação, o que cria um paradoxo clínico onde o paciente apresenta fenômenos trombóticos e hemorrágicos simultâneos.","O livedo reticular e a gangrena periférica são manifestações cutâneas da isquemia tecidual e necrose causadas pela obstrução do fluxo em microtrombos capilares.","No perfil laboratorial da CIVD aguda, observa-se tipicamente uma elevação dos níveis de fibrinogênio e um encurtamento do tempo de protrombina (TP), refletindo o estado de hipercoagulabilidade inicial provocado pela inflamação sistêmica.","A patogênese da CIVD na sepse é atenuada por uma resposta adaptativa do endotélio, que promove a suprarregulação de anticoagulantes naturais, como a Proteína C."],"o":["I, II e III","II, III e V","I, II e IV","I e III","III e IV"],"c":0,"x":"Gabarito: A. IV: na CIVD o fibrinogênio CAI e o TP ALARGA (consumo). V: há REDUÇÃO da proteína C. Ligação com Pato: meningococcemia → CIVD.","r":"SP3 · Doença meningocócica (CIVD)"},{"a":0,"p":1,"t":"Padrões de necrose (T11 Q10)","e":"Sobre os diferentes padrões de necrose, assinale a INCORRETA:","o":["A gangrena úmida resulta exclusivamente da infecção por bactérias anaeróbias em tecidos previamente viáveis, sem relação com isquemia local.","A necrose de coagulação é típica de infartos em órgãos sólidos, como coração e rins, nos quais a desnaturação proteica preserva temporariamente a arquitetura tecidual.","Na necrose de liquefação, frequentemente observada em abscessos bacterianos e no sistema nervoso central, ocorre digestão enzimática intensa do tecido acometido.","A necrose caseosa, característica da tuberculose, apresenta material amorfo eosinofílico e destruição da arquitetura tecidual no centro da lesão granulomatosa.","A necrose fibrinoide ocorre principalmente em vasos sanguíneos acometidos por vasculites imunológicas e hipertensão maligna, caracterizando-se por deposição de proteínas plasmáticas na parede vascular."],"c":0,"x":"Gabarito: A. A gangrena úmida parte de ISQUEMIA com infecção sobreposta. Ligação com Pato: abscesso cerebral = liquefativa; TB meníngea = caseosa; corpúsculo de Aschoff = centro fibrinoide.","r":"SP3 · Abscesso / Meningite TB"},{"a":0,"p":1,"t":"Barreira de filtração (T11 Q11)","e":"Sobre a fisiologia renal e a dinâmica de filtração, assinale a alternativa INCORRETA:","o":["A angiotensina II exerce um papel regulador no túbulo proximal ao inibir a reabsorção de sódio e água, atuando como um potente diurético endógeno.","A barreira de filtração glomerular é composta pelo endotélio fenestrado, pela membrana basal, rica em proteoglicanos aniônicos, e pelas fendas de filtração dos podócitos.","A permeabilidade da barreira é seletiva, permitindo que macromoléculas com forte carga negativa, como a albumina, não atravessem livremente para o espaço capsular em condições de normalidade.","O túbulo contorcido proximal é o principal sítio de reabsorção de glicose, aminoácidos e grande parte do sódio filtrado.","A filtração glomerular é um processo eminentemente circulatório, que depende da permeabilidade das membranas de filtração, da pressão arterial, e do tônus das arteríolas aferente e eferente."],"c":0,"x":"Gabarito: A. A angiotensina II ESTIMULA a reabsorção de Na⁺ e água no túbulo proximal (antidiurética). Ligação com Pato: lesão dessa barreira = síndrome nefrótica.","r":"SP1 · Síndrome nefrótica"}]};
